def _build_parameter_fields(self, template_validate):
    self.fields['password'] = forms.CharField(
        label=_('Password for user "%s"') % self.request.user.username,
        help_text=_('This is required for operations to be performed '
                    'throughout the lifecycle of the stack'),
        widget=forms.PasswordInput())

    self.help_text = template_validate['Description']

    params = template_validate.get('Parameters', {})
    if template_validate.get('ParameterGroups'):
        params_in_order = []
        for group in template_validate['ParameterGroups']:
            for param in group.get('parameters', []):
                if param in params:
                    params_in_order.append((param, params[param]))
    else:
        # no parameter groups, simply sorted to make the order fixed
        params_in_order = sorted(params.items())
    for param_key, param in params_in_order:
        field = None
        field_key = self.param_prefix + param_key
        field_args = {
            'initial': param.get('Default', None),
            'label': param.get('Label', param_key),
            'help_text': param.get('Description', ''),
            'required': param.get('Default', None) is None
        }

        param_type = param.get('Type', None)
        hidden = strutils.bool_from_string(param.get('NoEcho', 'false'))
        if 'CustomConstraint' in param:
            choices = self._populate_custom_choices(
                param['CustomConstraint'])
            field_args['choices'] = choices
            field = forms.ChoiceField(**field_args)

        elif 'AllowedValues' in param:
            choices = map(lambda x: (x, x), param['AllowedValues'])
            field_args['choices'] = choices
            field = forms.ChoiceField(**field_args)

        elif param_type == 'Json' and 'Default' in param:
            field_args['initial'] = json.dumps(param['Default'])
            field = forms.CharField(**field_args)

        elif param_type in ('CommaDelimitedList', 'String', 'Json'):
            if 'MinLength' in param:
                field_args['min_length'] = int(param['MinLength'])
                field_args['required'] = param.get('MinLength', 0) > 0
            if 'MaxLength' in param:
                field_args['max_length'] = int(param['MaxLength'])
            if hidden:
                field_args['widget'] = forms.PasswordInput()
            field = forms.CharField(**field_args)

        elif param_type == 'Number':
            if 'MinValue' in param:
                field_args['min_value'] = int(param['MinValue'])
            if 'MaxValue' in param:
                field_args['max_value'] = int(param['MaxValue'])
            field = forms.IntegerField(**field_args)

        # heat-api currently returns the boolean type in lowercase
        # (see https://bugs.launchpad.net/heat/+bug/1361448)
        # so for better compatibility both are checked here
        elif param_type in ('Boolean', 'boolean'):
            field = forms.BooleanField(**field_args)

        if field:
            self.fields[field_key] = field

def isURLInPortal(self, url, context=None):
        """ Check if a given url is on the same host and contains the portal
            path.  Used to ensure that login forms can determine relevant
            referrers (i.e. in portal).  Also return true for some relative
            urls if context is passed in to allow for url parsing. When context
            is not provided, assume that relative urls are in the portal. It is
            assumed that http://portal is the same portal as https://portal.

            External sites listed in 'allow_external_login_sites' of
            site_properties are also considered within the portal to allow for
            single sign on.
        """
        # sanitize url
        url = re.sub('^[\x00-\x20]+', '', url).strip()

        p_url = self()

        _, u_host, u_path, _, _, _ = urlparse(url)
        if not u_host and not u_path.startswith('/'):
            if context is None:
                return True  # old behavior
            if not context.isPrincipiaFolderish:
                useurl = context.aq_parent.absolute_url()
            else:
                useurl = context.absolute_url()
        else:
            useurl = p_url  # when u_path.startswith('/')
        if not useurl.endswith('/'):
            useurl += '/'

        # urljoin to current url to get an absolute path
        _, u_host, u_path, _, _, _ = urlparse(urljoin(useurl, url))

        # normalise to end with a '/' so /foobar is not considered within /foo
        if not u_path:
            u_path = '/'
        else:
            u_path = normpath(u_path)
            if not u_path.endswith('/'):
                u_path += '/'
        _, host, path, _, _, _ = urlparse(p_url)
        if not path.endswith('/'):
            path += '/'
        if host == u_host and u_path.startswith(path):
            return True

        props = getToolByName(self, 'portal_properties').site_properties
        for external_site in props.getProperty('allow_external_login_sites', []):
            _, host, path, _, _, _ = urlparse(external_site)
            if not path.endswith('/'):
                path += '/'
            if host == u_host and u_path.startswith(path):
                return True
        return False

def get_shares_data(self):
    share_nets_names = {}
    share_nets = manila.share_network_list(self.request)
    for share_net in share_nets:
        share_nets_names[share_net.id] = share_net.name
    try:
        shares = manila.share_list(self.request)
        for share in shares:
            share.share_network = \
                share_nets_names.get(share.share_network_id) or \
                share.share_network_id
            meta_str = utils.metadata_to_str(share.metadata)
            share.metadata = mark_safe(meta_str)

        snapshots = manila.share_snapshot_list(self.request, detailed=True)
        share_ids_with_snapshots = []
        for snapshot in snapshots:
            share_ids_with_snapshots.append(snapshot.to_dict()['share_id'])
        for share in shares:
            if share.to_dict()['id'] in share_ids_with_snapshots:
                setattr(share, 'has_snapshot', True)
            else:
                setattr(share, 'has_snapshot', False)
    except Exception:
        exceptions.handle(self.request,
                          _('Unable to retrieve share list.'))
        return []
    # Gather our tenants to correlate against IDs
    return shares

